answer:
sales = {"モニター": 10, "マウス": 40, "USBメモリ": 18, "キーボード": 25}

def top_sellers(sales, n):
    ordered = sorted(sales.items(), key=lambda kv: kv[1], reverse=True)
    return [name for name, count in ordered][:n]

print(top_sellers(sales, 2))
